import React, { useState, useEffect } from "react";
import axios from "axios";

const EmployeeList = () => {
  const [employees, setEmployees] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [departmentFilter, setDepartmentFilter] = useState("");

  useEffect(() => {
    fetchEmployees();
  }, []);

  const fetchEmployees = async () => {
    try {
      const response = await axios.get("http://localhost:9090/api/employees");
      setEmployees(response.data);
    } catch (error) {
      console.error("Çalışanları getirirken hata oluştu:", error);
    }
  };

  const filteredEmployees = employees.filter((employee) => {
    return (
      (searchTerm === "" || employee.name.toLowerCase().includes(searchTerm.toLowerCase())) &&
      (departmentFilter === "" || employee.department.toLowerCase() === departmentFilter.toLowerCase())
    );
  });

  return (
    <div className="max-w-4xl mx-auto p-6 bg-white shadow-md rounded-lg mt-8">
      <h2 className="text-2xl font-semibold text-gray-700 mb-4">Çalışan Listesi</h2>

      {/* Arama Kutusu */}
      <input
        type="text"
        placeholder="Çalışan Ara..."
        className="w-full p-2 border rounded-md mb-4"
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
      />

      {/* Departman Filtreleme */}
      <select
        className="w-full p-2 border rounded-md mb-4"
        value={departmentFilter}
        onChange={(e) => setDepartmentFilter(e.target.value)}
      >
        <option value="">Tüm Departmanlar</option>
        <option value="IT">IT</option>
        <option value="HR">HR</option>
        <option value="Finance">Finance</option>
      </select>

      {/* Çalışan Listesi */}
      <ul className="divide-y divide-gray-300">
        {filteredEmployees.length > 0 ? (
          filteredEmployees.map((employee) => (
            <li key={employee.id} className="p-4 flex justify-between items-center">
              <div>
                <p className="text-lg font-semibold">{employee.name} {employee.surname}</p>
                <p className="text-gray-500">{employee.email}</p>
                <p className="text-sm text-gray-600">Departman: {employee.department}</p>
              </div>
              <button className="px-4 py-2 bg-blue-500 text-white rounded-md hover:bg-blue-600">
                Detay
              </button>
            </li>
          ))
        ) : (
          <p className="text-center text-gray-500">Çalışan bulunamadı.</p>
        )}
      </ul>
    </div>
  );
};

export default EmployeeList;
